{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C22"],
      "claim": "Loteprednol etabonate, a corticosteroid ester prodrug, showed very low oral bioavailability in healthy volunteers after a 40 mg oral dose, supporting low F for the similarly ester/acetal prodrug query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C52"],
      "claim": "Mometasone, an inhaled corticosteroid with ester functionality, is reported to have low oral bioavailability (<1%), consistent with the query's inhaled prodrug design.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Beclomethasone dipropionate, an inhaled corticosteroid diester prodrug, has an oral bioavailability of 15%, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Deflazacort, the closest structural analogue, has an absolute oral bioavailability of 68% in volunteers, supporting high F; however, it is an oral prodrug with an oxazoline ring rather than the inhaled acetal/ester design of the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C54"],
      "claim": "Dexamethasone, a non-prodrug corticosteroid, has an absolute oral bioavailability of 62% in humans, but lacks the ester/acetal prodrug moieties that limit the query's oral absorption.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Prediction is low. Although several active corticosteroids and the close analogue deflazacort show high oral bioavailability, the query is ciclesonide, an inhaled corticosteroid prodrug with a 21-isobutyrate ester and 16,17-acetal. The most functionally relevant prodrug analogues (loteprednol etabonate, mometasone, beclomethasone dipropionate) show very low to low oral bioavailability, and the prodrug design is intended to minimize systemic oral exposure. Thus F <20% is better supported.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for ciclesonide is present in the evidence set.",
    "The closest high-similarity analogue deflazacort is an oral prodrug with different prodrug chemistry.",
    "Beclomethasone dipropionate data are mixed around the 20% threshold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

